```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>

using namespace std;

int main() {
    // Nom du fichier à lire
    const string fileName = "input.txt";

    // Mot à chercher dans le fichier
    const string searchWord = "example";

    // Variable pour compter le nombre d'occurrences du mot
    int count = 0;

    // Ouvrir le fichier en lecture
    ifstream file(fileName);

    if (!file.is_open()) {
        cout << "Impossible d'ouvrir le fichier " << fileName << endl;
        return 1;
    }

    // Boucle pour lire chaque ligne du fichier
    string line;
    while (getline(file, line)) {

        // Convertir la ligne en petit caractères pour la comparaison
        transform(line.begin(), line.end(), line.begin(), ::tolower);

        // Chercher le mot dans la ligne
        size_t pos = line.find(searchWord);

        // Tant que le mot est trouvé dans la ligne
        while (pos != string::npos) {
            count++; // Incrémenter le compteur
            pos = line.find(searchWord, pos + 1); // Rechercher le mot à partir de la position suivante
        }
    }

    // Fermer le fichier
    file.close();

    // Afficher le nombre d'occurrences du mot dans le fichier
    cout << "Le mot \"" << searchWord << "\" apparaît " << count << " fois dans le fichier " << fileName << endl;

    return 0;
}
```

Le programme utilise la bibliothèque iostream pour afficher les résultats, la bibliothèque fstream pour lire le fichier, la bibliothèque string pour manipuler les chaînes de caractères, et la fonction transform() pour convertir les caractères en petit.

Il vérifie que le fichier est ouvert, lit chaque ligne du fichier, convertit la ligne en petit caractères pour la comparaison, recherche le mot dans la ligne, et incrémente le compteur de chaque occurrence trouvée. Enfin, il ferme le fichier et affiche le nombre d'occurrences du mot dans le fichier.

